var t = 0
var x = 0
var circles = 24;

function draw_mouse(x, y, size = 1, angle = 0) {
	push()
	beginShape(); 
	translate(x, y)
	rotate(angle)
	vertex(0, 0)
	vertex(0, 0 + 17 * size)
	vertex(0 + 4 * size, 0 + 13 * size)
	vertex(0 + 7 * size, 0 + 20 * size)
	vertex(0 + 10 * size, 0 + 19 * size)
	vertex(0 + 7 * size, 0 + 12 * size)
	vertex(0 + 12 * size, 0 + 12 * size)
	endShapepop()
}

function draw_mouse_circle(radius, count) {
	x = noise(radius / 100 + t)
	for (let i = x; i < TWO_PI + x; i += (Math.max(0.001, Math.abs(PI / count)) || 1)) {
		var x = cos(i) * radius * (1 + sin(explodeIndex)*sin(radius+explodeIndex*2));
		let y = sin(i) * radius * (1 + sin(explodeIndex)*sin(radius+explodeIndex*2));
		draw_mouse(width / 2 + x, height / 2 + y, 1, 3.25 * PI / 2 + i)
	}
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	fill(0)
	stroke(255)
	strokeWeight(1.2)
	noiseDetail(2, 0.2)
	angleMode(RADIANS);
	noCursor();
}

function draw() {
	background(0);
	if (explode) {
		explodeIndex += PI / 60;
		if (explodeIndex >= PI) {
			explodeIndex = 0;
			explode = false;
		}
	}
	translate((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2);
	draw_mouse(width / 2 - 5, height / 2 - 10)
	for (i = 1; i < circles; i++) {
		draw_mouse_circle(width / (circles / i), i * 3)
	}
	t += 0.01
	translate(-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + width / 2, -(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + height / 2);

}

var explodeIndex = 0;
var explode = false;

